%% fig_export_panels
% Save the component panels of the main figures as PNGs in
% ugly_figures/all_figs/panels/FigN (via claude/pb_export_panels.m, which
% hides everything outside a panel and exportgraphics-crops the rest, so each
% PNG is pixel-identical to that region of the full figure).
%
% Each figure is regenerated by running its script (Fig 1 ~7 min) rather than
% loaded from a saved .fig: .fig files drop the undocumented 4th (alpha)
% element of line Color, so e.g. Fig 1's translucent gray per-fly lag traces
% come back solid black.
%
% Set panel_figs (e.g. panel_figs = 2) before running to export only some
% figures; default is all of them. Fig 1 needs R2023a (medfilt1).

%% paths
repo_root = fileparts(fileparts(fileparts(mfilename('fullpath')))); % ugly_figures/scripts -> repo root
addpath(fullfile(repo_root,'claude'))
panels_dir = fullfile(repo_root,'ugly_figures','all_figs','panels');
if ~exist('panel_figs','var'); panel_figs = 1:3; end

%% Figure 1: rows 1-4 (example flies + correlation summary) | rows 5-6 (GRAB/jRGECo1a co-imaging)
if ismember(1,panel_figs)
Figure_1_claude
f1 = gcf;
repo_root = fileparts(fileparts(fileparts(which('fig_export_panels')))); % the script overwrites repo_root/workspace
addpath(fullfile(repo_root,'claude'))
panels_dir = fullfile(repo_root,'ugly_figures','all_figs','panels');
axs = findall(f1,'Type','axes');
ttl = arrayfun(@(a) strjoin(cellstr(a.Title.String),' '), axs, 'UniformOutput', false);
top = arrayfun(@(a) sum(getpixelposition(a,true).*[0 1 0 1]), axs);
% co-imaging block = row 5 (titled "co-imaged ..." / "both channels") and everything below it
is_co = top <= max(top(contains(ttl,{'co-imaged','both channels'}))) + 1;
fprintf('Fig1: %d axes in rows 1-4, %d in co-imaging rows\n', sum(~is_co), sum(is_co));
tic
files = pb_export_panels(f1, fullfile(panels_dir,'Fig1'), 'F1', ...
    'Groups', {axs(~is_co), axs(is_co)}, 'Names', {'F1_top','F1_coimg'});
fprintf('Fig1: wrote %s (%.0f s)\n', strjoin(files,', '), toc);
close(f1)
end

%% Figure 2: per big column (syt7f left, GRAB(DA2m) right): rows 1-2 (heatmap + frames) | rows 3-5 (example traces) | row 6 (R^2 + tuning)
if ismember(2,panel_figs)
Figure_2_claude
f2 = gcf;
repo_root = fileparts(fileparts(fileparts(which('fig_export_panels'))));
addpath(fullfile(repo_root,'claude'))
panels_dir = fullfile(repo_root,'ugly_figures','all_figs','panels');
% 15x4 tiledlayout (Figure_2_claude.m render_variant_column): tile rows 1-6 =
% figure rows 1-2, 7-12 = rows 3-5, 13-15 = row 6; tile cols 1-2 = syt7f
axs = findall(f2,'Type','axes');
tile = arrayfun(@(a) a.Layout.Tile, axs);
tile_row = floor((tile-1)/4) + 1;
is_left = mod(tile-1,4) < 2;
row_grp = 1 + (tile_row >= 7) + (tile_row >= 13);
col_tag = {'syt','grab'}; row_tag = {'r12','r345','r6'};
groups = {}; names = {};
for c = 1:2
    for g = 1:3
        groups{end+1} = axs(is_left == (c==1) & row_grp == g); %#ok<SAGROW>
        names{end+1} = sprintf('F2_%s_%s', col_tag{c}, row_tag{g}); %#ok<SAGROW>
    end
end
fprintf('Fig2: axes per panel: %s\n', mat2str(cellfun(@numel,groups)));
tic
files = pb_export_panels(f2, fullfile(panels_dir,'Fig2'), 'F2', 'Groups', groups, 'Names', names);
fprintf('Fig2: wrote %s (%.0f s)\n', strjoin(files,', '), toc);
close(f2)
end

%% Figure 3: rows 1-2 (example stims + average bump response) | row 3 (mobility example) | row 4 (mobility summaries)
if ismember(3,panel_figs)
% fig3 is 1700x1700 px, taller than the 1080 px screen: shortly after it is
% created its canvas gets clamped to the screen (even invisible, in batch), so
% any later render/position query sees a squashed layout. The script's own
% exportgraphics call right after building it still has the full layout, so
% the panels are cut from that PNG (exports/Figure_3_claude.png) by
% pb_split_png_rows. To save time and leave the other outputs alone, run a
% temporary copy of Figure_3_claude.m without its scratch stim-side-flip and
% Figure_3_dopamine sections (kept in the same folder: the script finds
% repo_root from its own location).
src = fileread(which('Figure_3_claude'));
i0 = strfind(src, '%% ===================== SCRATCH: verbose walkthrough');
i1 = strfind(src, '%% ===================== functions');
src = [src(1:i0(1)-1) src(i1(1):end)];
tmp_script = fullfile(fileparts(which('Figure_3_claude')), 'Figure_3_claude_mainonly.m');
fid = fopen(tmp_script,'w'); fwrite(fid, src); fclose(fid);
rehash
try
    Figure_3_claude_mainonly
catch err
    delete(tmp_script); rethrow(err)
end
delete(tmp_script)
repo_root = fileparts(fileparts(fileparts(which('fig_export_panels'))));
addpath(fullfile(repo_root,'claude'))
panels_dir = fullfile(repo_root,'ugly_figures','all_figs','panels');
full_png = fullfile(repo_root,'ugly_figures','exports','Figure_3_claude.png');
info = imfinfo(full_png);
fprintf('Fig3: full export %dx%d\n', info.Width, info.Height);
assert(info.Height > 0.9*info.Width, 'Figure_3_claude.png looks screen-clamped (%dx%d)', info.Width, info.Height);
% cut fractions sit in the gaps above the row-3 titles and above the row-4 titles
files = pb_split_png_rows(full_png, [0.517 0.767], {'F3_r12','F3_r3','F3_r4'}, fullfile(panels_dir,'Fig3'));
fprintf('Fig3: wrote %s\n', strjoin(files,', '));
close all
end
